.sc-tw *,.sc-tw *::before,.sc-tw *::after{box-sizing:border-box;margin:0;padding:0}.sc-tw :root{
  --amber:oklch(85% 0.1 45);
  --amber-glow:oklch(80% 0.12 42 / 0.4);
  --rose:oklch(75% 0.1 340);
  --rose-glow:oklch(75% 0.1 340 / 0.25);
  --sage:oklch(72% 0.08 160);
  --sage-glow:oklch(72% 0.08 160 / 0.2);
  --pearl:oklch(96% 0.02 80);
  --deep:oklch(12% 0.02 260);
  --midnight:oklch(8% 0.015 260);
  --text-primary:oklch(94% 0.01 60);
  --text-secondary:oklch(78% 0.02 50);
  --text-muted:oklch(60% 0.02 50);
  --glass-bg:oklch(18% 0.03 260 / 0.55);
  --glass-border:oklch(85% 0.05 60 / 0.12);
  --glass-border-hover:oklch(85% 0.08 45 / 0.3);
  --serif:'DM Serif Display',serif;
  --serif-alt:'Instrument Serif',serif;
  --sans:'Syne',sans-serif;
  --data:'Space Grotesk',sans-serif;
}.sc-tw html{scroll-behavior:smooth;overflow-x:hidden}.sc-tw{
  background:var(--midnight);
  color:var(--text-primary);
  font-family:var(--sans);
  min-height:100vh;
  overflow-x:hidden;
  cursor:none;
}.sc-tw ::-webkit-scrollbar{width:3px}.sc-tw ::-webkit-scrollbar-track{background:transparent}.sc-tw ::-webkit-scrollbar-thumb{background:oklch(85% 0.08 45 / 0.4);border-radius:99px}.sc-tw .cursor{
  position:fixed;width:12px;height:12px;
  background:var(--amber);border-radius:50%;
  pointer-events:none;z-index:9999;
  transform:translate(-50%,-50%);
  transition:transform 0.1s ease,width 0.3s ease,height 0.3s ease,opacity 0.3s ease;
  mix-blend-mode:screen;
}.sc-tw .cursor-trail{
  position:fixed;width:40px;height:40px;
  border:1px solid oklch(85% 0.1 45 / 0.3);
  border-radius:50%;pointer-events:none;z-index:9998;
  transform:translate(-50%,-50%);
  transition:transform 0.25s ease,width 0.4s ease,height 0.4s ease;
}.sc-tw .hero{
  position:relative;height:100vh;overflow:hidden;
  display:flex;align-items:center;justify-content:center;
}.sc-tw .video-portal{
  position:absolute;inset:0;z-index:0;
}.sc-tw .video-portal video{
  width:100%;height:100%;object-fit:cover;
  filter:brightness(0.75);
}.sc-tw .video-portal::after{
  content:'';position:absolute;inset:0;
  background:radial-gradient(ellipse 80% 100% at 50% 60%,transparent 45%,var(--midnight) 92%);
  pointer-events:none;
}.sc-tw .atmospheric-mask{
  position:absolute;
  top:50%;left:50%;
  transform:translate(-50%,-50%);
  width:75vw;height:65vh;
  z-index:1;
  border-radius:60% 40% 55% 45% / 45% 55% 40% 60%;
  mask-image:radial-gradient(ellipse 85% 85% at 50% 50%,black 40%,transparent 75%);
  -webkit-mask-image:radial-gradient(ellipse 85% 85% at 50% 50%,black 40%,transparent 75%);
  animation:blob-drift 18s ease-in-out infinite;
  overflow:hidden;
}.sc-tw .atmospheric-mask video{
  width:130%;height:130%;object-fit:cover;
  margin:-15%;
}
@keyframes blob-drift{0%,100%{border-radius:60% 40% 55% 45% / 45% 55% 40% 60%;transform:translate(-50%,-50%) scale(1)}33%{border-radius:40% 60% 45% 55% / 55% 40% 65% 35%;transform:translate(-50%,-50%) scale(1.03)}66%{border-radius:55% 45% 60% 40% / 40% 65% 35% 60%;transform:translate(-50%,-50%) scale(0.97)}
}.sc-tw .light-corridor{
  position:absolute;inset:0;z-index:2;pointer-events:none;
  background:radial-gradient(ellipse at 50% 50%,oklch(85% 0.08 30 / 0.18) 0%,oklch(75% 0.1 340 / 0.07) 40%,transparent 80%);
}.sc-tw .hero-content{
  position:relative;z-index:10;
  text-align:center;
  max-width:900px;
  padding:0 2rem;
}.sc-tw .hero-eyebrow{
  font-family:var(--data);
  font-size:0.72rem;
  font-weight:400;
  letter-spacing:0.35em;
  text-transform:uppercase;
  color:var(--text-muted);
  margin-bottom:2rem;
  opacity:0;
  animation:fade-rise 1.2s 0.4s ease forwards;
}.sc-tw .hero-title{
  font-family:var(--serif);
  font-size:clamp(3.2rem,8vw,8rem);
  line-height:0.9;
  margin-bottom:1.5rem;
  opacity:0;
  animation:fade-rise 1.4s 0.6s ease forwards;
}.sc-tw .hero-title em{
  font-style:italic;
  color:var(--amber);
  display:block;
}.sc-tw .hero-subtitle{
  font-family:var(--data);
  font-size:0.9rem;
  font-weight:300;
  color:var(--text-secondary);
  letter-spacing:0.08em;
  max-width:480px;
  margin:0 auto 3rem;
  line-height:1.7;
  opacity:0;
  animation:fade-rise 1.4s 0.9s ease forwards;
}.sc-tw .hero-cta-group{
  display:flex;align-items:center;justify-content:center;gap:1.5rem;
  opacity:0;
  animation:fade-rise 1.2s 1.2s ease forwards;
}.sc-tw .btn-liquid{
  position:relative;
  padding:1rem 2.5rem;
  border-radius:40% 60% 70% 30% / 40% 50% 60% 50%;
  border:1px solid var(--glass-border-hover);
  background:oklch(85% 0.08 45 / 0.08);
  color:var(--text-primary);
  font-family:var(--data);
  font-size:0.82rem;
  letter-spacing:0.15em;
  text-transform:uppercase;
  cursor:none;
  overflow:hidden;
  transition:border-radius 0.6s ease,border-color 0.3s ease,background 0.3s ease;
  text-decoration:none;
  display:inline-flex;align-items:center;gap:0.75rem;
}.sc-tw .btn-liquid::before{
  content:'';
  position:absolute;inset:0;
  background:radial-gradient(circle at var(--mx,50%) var(--my,50%),oklch(85% 0.1 45 / 0.25) 0%,transparent 60%);
  opacity:0;
  transition:opacity 0.3s ease;
}.sc-tw .btn-liquid::after{
  content:'';
  position:absolute;
  top:-50%;left:-50%;
  width:200%;height:200%;
  background:conic-gradient(transparent 30%,oklch(85% 0.1 45 / 0.15) 40%,transparent 50%);
  animation:shimmer-spin 4s linear infinite;
  opacity:0;
  transition:opacity 0.4s ease;
}.sc-tw .btn-liquid:hover{
  border-radius:60% 40% 30% 70% / 60% 30% 70% 40%;
  border-color:oklch(85% 0.1 45 / 0.5);
  background:oklch(85% 0.08 45 / 0.15);
}.sc-tw .btn-liquid:hover::before,.sc-tw .btn-liquid:hover::after{opacity:1}
@keyframes shimmer-spin{to{transform:rotate(360deg)}}.sc-tw .btn-ghost{
  padding:1rem 2rem;
  background:transparent;
  border:none;
  color:var(--text-muted);
  font-family:var(--data);
  font-size:0.82rem;
  letter-spacing:0.12em;
  text-transform:uppercase;
  cursor:none;
  transition:color 0.3s ease;
  text-decoration:none;
}.sc-tw .btn-ghost:hover{color:var(--text-secondary)}

@keyframes fade-rise{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:translateY(0)}
}.sc-tw .scroll-hint{
  position:absolute;bottom:3rem;left:50%;
  transform:translateX(-50%);
  z-index:10;
  display:flex;flex-direction:column;align-items:center;gap:0.75rem;
  opacity:0;animation:fade-rise 1s 2s ease forwards;
}.sc-tw .scroll-hint span{
  font-family:var(--data);font-size:0.65rem;
  letter-spacing:0.3em;text-transform:uppercase;
  color:var(--text-muted);
}.sc-tw .scroll-line{
  width:1px;height:48px;
  background:linear-gradient(to bottom,var(--amber-glow),transparent);
  animation:scroll-pulse 2s ease-in-out infinite;
}
@keyframes scroll-pulse{0%,100%{opacity:0.3;transform:scaleY(1)}50%{opacity:1;transform:scaleY(1.2)}
}.sc-tw nav{
  position:fixed;top:0;left:0;right:0;z-index:100;
  padding:1.75rem 4rem;
  display:flex;align-items:center;justify-content:space-between;
  transition:background 0.5s ease,backdrop-filter 0.5s ease;
}.sc-tw nav.scrolled{
  background:oklch(10% 0.02 260 / 0.7);
  backdrop-filter:blur(20px) saturate(1.2);
  border-bottom:1px solid var(--glass-border);
}.sc-tw .nav-logo{
  font-family:var(--serif);
  font-size:1.2rem;
  color:var(--text-primary);
  letter-spacing:0.02em;
  text-decoration:none;
}.sc-tw .nav-logo span{color:var(--amber)}.sc-tw .nav-links{
  display:flex;align-items:center;gap:3rem;
  list-style:none;
}.sc-tw .nav-links a{
  font-family:var(--data);
  font-size:0.75rem;
  letter-spacing:0.2em;
  text-transform:uppercase;
  color:var(--text-muted);
  text-decoration:none;
  transition:color 0.3s ease;
  position:relative;
}.sc-tw .nav-links a::after{
  content:'';
  position:absolute;bottom:-4px;left:0;right:0;
  height:1px;
  background:var(--amber);
  transform:scaleX(0);
  transform-origin:left;
  transition:transform 0.3s ease;
}.sc-tw .nav-links a:hover{color:var(--text-primary)}.sc-tw .nav-links a:hover::after{transform:scaleX(1)}.sc-tw .section-divider{
  height:1px;
  background:radial-gradient(ellipse 60% 100% at 50% 50%,oklch(85% 0.1 45 / 0.4),transparent);
  margin:0 8vw;
}.sc-tw section{padding:8rem 0}.sc-tw .container{max-width:1320px;margin:0 auto;padding:0 4rem}.sc-tw .section-label{
  font-family:var(--data);
  font-size:0.65rem;
  letter-spacing:0.4em;
  text-transform:uppercase;
  color:var(--text-muted);
  margin-bottom:1rem;
}.sc-tw .manifesto{
  background:transparent;
  position:relative;
}.sc-tw .manifesto::before{
  content:'';
  position:absolute;
  top:0;left:50%;transform:translateX(-50%);
  width:70vw;height:100%;
  background:radial-gradient(ellipse 100% 80% at 50% 30%,oklch(85% 0.08 45 / 0.06),transparent 70%);
  pointer-events:none;
}.sc-tw .manifesto-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:8rem;
  align-items:center;
}.sc-tw .manifesto-text h2{
  font-family:var(--serif);
  font-size:clamp(2.4rem,4vw,4.2rem);
  line-height:1.05;
  margin-bottom:2rem;
}.sc-tw .manifesto-text h2 em{
  font-style:italic;
  color:oklch(80% 0.1 340);
}.sc-tw .manifesto-text p{
  font-family:var(--data);
  font-size:0.92rem;
  font-weight:300;
  line-height:1.85;
  color:var(--text-secondary);
  margin-bottom:1.5rem;
}.sc-tw .manifesto-metrics{
  display:grid;grid-template-columns:1fr 1fr;gap:1.5rem;
}.sc-tw .metric-orb{
  padding:2.5rem 2rem;
  border-radius:40% 60% 55% 45% / 50% 40% 60% 50%;
  background:var(--glass-bg);
  border:1px solid var(--glass-border);
  backdrop-filter:blur(20px);
  text-align:center;
  transition:border-radius 0.8s ease,border-color 0.4s ease,transform 0.4s ease;
  animation:float-orb var(--dur,6s) ease-in-out infinite;
  animation-delay:var(--delay,0s);
}.sc-tw .metric-orb:hover{
  border-radius:60% 40% 45% 55% / 40% 60% 50% 60%;
  border-color:oklch(85% 0.1 45 / 0.35);
  transform:translateY(-4px);
}
@keyframes float-orb{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}
}.sc-tw .metric-value{
  font-family:var(--serif);
  font-size:3rem;
  color:var(--amber);
  line-height:1;
  margin-bottom:0.5rem;
}.sc-tw .metric-label{
  font-family:var(--data);
  font-size:0.72rem;
  letter-spacing:0.15em;
  text-transform:uppercase;
  color:var(--text-muted);
}.sc-tw .pillars{padding:8rem 0;position:relative}.sc-tw .pillars::before{
  content:'';position:absolute;
  left:0;right:0;top:0;bottom:0;
  background:radial-gradient(ellipse 80% 60% at 20% 50%,oklch(72% 0.08 160 / 0.06),transparent 60%),
             radial-gradient(ellipse 60% 80% at 80% 60%,oklch(75% 0.1 340 / 0.05),transparent 60%);
  pointer-events:none;
}.sc-tw .pillars-header{
  text-align:center;
  margin-bottom:5rem;
}.sc-tw .pillars-header h2{
  font-family:var(--serif);
  font-size:clamp(2rem,3.5vw,3.5rem);
  line-height:1.1;
}.sc-tw .pillars-header h2 em{font-style:italic;color:var(--sage)}.sc-tw .pillars-header p{
  font-family:var(--data);
  font-size:0.9rem;
  font-weight:300;
  color:var(--text-muted);
  max-width:500px;
  margin:1.5rem auto 0;
  line-height:1.7;
}.sc-tw .pillars-flow{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:0;
  position:relative;
}.sc-tw .pillar-card{
  padding:3rem 2rem;
  position:relative;
  border-radius:40% 60% 70% 30% / 40% 50% 60% 50%;
  background:oklch(16% 0.02 260 / 0.6);
  border:1px solid var(--glass-border);
  margin:0.75rem;
  backdrop-filter:blur(16px);
  transition:border-radius 0.9s ease,transform 0.4s ease,background 0.4s ease,border-color 0.4s ease;
  overflow:hidden;
}.sc-tw .pillar-card::before{
  content:'';
  position:absolute;inset:0;
  background:radial-gradient(circle at 50% 0%,var(--card-glow,oklch(85% 0.1 45 / 0.1)) 0%,transparent 60%);
  opacity:0;transition:opacity 0.4s ease;
}.sc-tw .pillar-card:hover{
  border-radius:60% 40% 30% 70% / 50% 60% 40% 50%;
  transform:translateY(-8px) rotate(-0.5deg);
  background:oklch(18% 0.03 260 / 0.75);
  border-color:var(--glass-border-hover);
}.sc-tw .pillar-card:hover::before{opacity:1}.sc-tw .pillar-card:nth-child(2){--card-glow:oklch(72% 0.08 160 / 0.12)}.sc-tw .pillar-card:nth-child(3){--card-glow:oklch(75% 0.1 340 / 0.1)}.sc-tw .pillar-card:nth-child(4){--card-glow:oklch(75% 0.12 250 / 0.1)}.sc-tw .pillar-icon{
  width:48px;height:48px;margin-bottom:1.75rem;
  border-radius:50%;
  background:oklch(85% 0.08 45 / 0.08);
  border:1px solid var(--glass-border);
  display:flex;align-items:center;justify-content:center;
}.sc-tw .pillar-icon svg{width:22px;height:22px;stroke:var(--amber);fill:none;stroke-width:1.5}.sc-tw .pillar-card:nth-child(2) .pillar-icon svg{stroke:var(--sage)}.sc-tw .pillar-card:nth-child(3) .pillar-icon svg{stroke:oklch(75% 0.1 340)}.sc-tw .pillar-card:nth-child(4) .pillar-icon svg{stroke:oklch(72% 0.1 250)}.sc-tw .pillar-tag{
  font-family:var(--data);
  font-size:0.62rem;
  letter-spacing:0.3em;
  text-transform:uppercase;
  color:var(--text-muted);
  margin-bottom:0.75rem;
}.sc-tw .pillar-title{
  font-family:var(--serif-alt);
  font-size:1.4rem;
  margin-bottom:1rem;
  color:var(--text-primary);
}.sc-tw .pillar-body{
  font-family:var(--data);
  font-size:0.82rem;
  line-height:1.8;
  color:var(--text-muted);
  font-weight:300;
}.sc-tw .projects{padding:8rem 0;position:relative}.sc-tw .projects-header{
  display:flex;align-items:flex-end;justify-content:space-between;
  margin-bottom:4rem;
}.sc-tw .projects-header h2{
  font-family:var(--serif);
  font-size:clamp(2.2rem,3.5vw,3.8rem);
  line-height:1;
  max-width:500px;
}.sc-tw .projects-header h2 em{font-style:italic;color:var(--amber)}.sc-tw .projects-nav{
  display:flex;gap:0.75rem;
}.sc-tw .proj-btn{
  width:42px;height:42px;
  border-radius:50%;
  background:transparent;
  border:1px solid var(--glass-border);
  color:var(--text-muted);
  cursor:none;
  display:flex;align-items:center;justify-content:center;
  transition:border-color 0.3s ease,background 0.3s ease,color 0.3s ease;
  font-size:1.1rem;
}.sc-tw .proj-btn:hover{
  border-color:var(--glass-border-hover);
  background:oklch(85% 0.08 45 / 0.08);
  color:var(--text-primary);
}.sc-tw .projects-track-wrapper{overflow:hidden}.sc-tw .projects-track{
  display:flex;gap:1.5rem;
  transition:transform 0.7s cubic-bezier(0.4,0,0.2,1);
}.sc-tw .project-card{
  flex:0 0 calc(50% - 0.75rem);
  border-radius:40% 60% 50% 50% / 50% 40% 60% 50%;
  overflow:hidden;
  position:relative;
  aspect-ratio:16/10;
  transition:border-radius 0.9s ease,transform 0.5s ease;
  background:oklch(15% 0.03 260);
  border:1px solid var(--glass-border);
  cursor:none;
}.sc-tw .project-card:hover{
  border-radius:55% 45% 40% 60% / 40% 60% 50% 50%;
  transform:scale(1.02);
}.sc-tw .project-bg{
  position:absolute;inset:0;
  background:var(--project-bg);
  filter:saturate(1.2) brightness(0.6);
  transition:filter 0.5s ease,transform 0.7s ease;
}.sc-tw .project-card:hover .project-bg{
  filter:saturate(1.4) brightness(0.7);
  transform:scale(1.05);
}.sc-tw .project-card:nth-child(1){--project-bg:radial-gradient(ellipse at 30% 60%,oklch(65% 0.15 160),oklch(20% 0.05 200))}.sc-tw .project-card:nth-child(2){--project-bg:radial-gradient(ellipse at 70% 40%,oklch(60% 0.12 340),oklch(18% 0.04 280))}.sc-tw .project-card:nth-child(3){--project-bg:radial-gradient(ellipse at 50% 70%,oklch(70% 0.1 45),oklch(20% 0.06 260))}.sc-tw .project-card:nth-child(4){--project-bg:radial-gradient(ellipse at 40% 50%,oklch(55% 0.1 250),oklch(15% 0.04 280))}.sc-tw .project-info{
  position:absolute;bottom:0;left:0;right:0;
  padding:2.5rem;
  background:linear-gradient(to top,oklch(8% 0.02 260 / 0.9) 0%,transparent 100%);
}.sc-tw .project-kv{
  font-family:var(--data);
  font-size:0.62rem;
  letter-spacing:0.3em;
  text-transform:uppercase;
  color:var(--amber);
  margin-bottom:0.6rem;
}.sc-tw .project-title{
  font-family:var(--serif);
  font-size:1.8rem;
  margin-bottom:0.4rem;
}.sc-tw .project-loc{
  font-family:var(--data);
  font-size:0.78rem;
  color:var(--text-muted);
  letter-spacing:0.08em;
}.sc-tw .data-strip{
  padding:5rem 0;
  position:relative;
  overflow:hidden;
}.sc-tw .data-strip::before{
  content:'';
  position:absolute;inset:0;
  background:oklch(14% 0.025 260 / 0.8);
  backdrop-filter:blur(2px);
}.sc-tw .data-strip::after{
  content:'';
  position:absolute;top:0;left:0;right:0;height:1px;
  background:radial-gradient(ellipse 50% 100% at 50% 0%,oklch(85% 0.1 45 / 0.3),transparent);
}.sc-tw .data-row{
  position:relative;z-index:1;
  display:grid;
  grid-template-columns:repeat(5,1fr);
  gap:1px;
}.sc-tw .data-cell{
  padding:2.5rem 2rem;
  text-align:center;
  border-right:1px solid var(--glass-border);
  position:relative;
}.sc-tw .data-cell:last-child{border-right:none}.sc-tw .data-cell-num{
  font-family:var(--serif);
  font-size:2.8rem;
  color:var(--text-primary);
  line-height:1;
  margin-bottom:0.4rem;
}.sc-tw .data-cell-num span{
  font-size:1.4rem;
  color:var(--amber);
}.sc-tw .data-cell-label{
  font-family:var(--data);
  font-size:0.65rem;
  letter-spacing:0.25em;
  text-transform:uppercase;
  color:var(--text-muted);
}.sc-tw .philosophy{
  padding:8rem 0;
  position:relative;
}.sc-tw .philosophy::before{
  content:'';
  position:absolute;
  right:-20%;top:10%;
  width:60vw;height:60vw;
  border-radius:50%;
  background:radial-gradient(circle,oklch(75% 0.1 340 / 0.04) 0%,transparent 65%);
  pointer-events:none;
}.sc-tw .philosophy-inner{
  display:grid;
  grid-template-columns:2fr 3fr;
  gap:8rem;
  align-items:start;
}.sc-tw .philosophy-sticky{
  position:sticky;top:10rem;
}.sc-tw .philosophy-sticky h2{
  font-family:var(--serif);
  font-size:clamp(2rem,3vw,3.2rem);
  line-height:1.05;
  margin-bottom:2rem;
}.sc-tw .philosophy-sticky h2 em{font-style:italic;color:oklch(80% 0.1 340)}.sc-tw .philosophy-sticky p{
  font-family:var(--data);
  font-size:0.85rem;
  font-weight:300;
  line-height:1.8;
  color:var(--text-secondary);
  margin-bottom:2.5rem;
}.sc-tw .phil-line-item{
  display:flex;gap:1.25rem;align-items:start;
  padding:2rem 0;
  border-top:1px solid var(--glass-border);
  position:relative;
}.sc-tw .phil-line-item::after{
  content:'';
  position:absolute;top:0;left:0;right:0;height:1px;
  background:radial-gradient(ellipse 30% 100% at 50% 0%,oklch(85% 0.1 45 / 0.25),transparent);
}.sc-tw .phil-number{
  font-family:var(--serif-alt);
  font-size:1rem;
  color:var(--amber);
  font-style:italic;
  min-width:2rem;
  margin-top:0.1rem;
}.sc-tw .phil-content h3{
  font-family:var(--sans);
